const query = String(input.query || '').trim();
const limit = Math.max(1, Math.min(Number(input.limit) || 5, 10));
const endpoint = new URL('/search/repositories', 'https://api.github.com');
endpoint.searchParams.set('q', query);
endpoint.searchParams.set('per_page', String(limit));
const pageUrl = new URL('/search', 'https://github.com');
pageUrl.searchParams.set('q', query);
pageUrl.searchParams.set('type', 'repositories');
const response = await fetch(endpoint.href, { credentials: 'omit', headers: { Accept: 'application/vnd.github+json' } });
if (response.status === 403 || response.status === 429) {
  const remaining = response.headers && typeof response.headers.get === 'function' ? response.headers.get('x-ratelimit-remaining') : null;
  const reset = response.headers && typeof response.headers.get === 'function' ? response.headers.get('x-ratelimit-reset') : null;
  const retryAfter = response.headers && typeof response.headers.get === 'function' ? response.headers.get('retry-after') : null;
  let message = '';
  try {
    const payload = await response.json();
    if (payload && typeof payload.message === 'string') message = payload.message.trim().slice(0, 300);
  } catch {}
  const limited = response.status === 429 || remaining === '0' || Boolean(retryAfter) || /rate limit|secondary rate/i.test(message);
  return Object.assign(
    { success: false, status: limited ? 'rate_limited' : 'forbidden', query, httpStatus: response.status, source: response.url || endpoint.href },
    reset ? { rateLimitReset: reset } : null,
    retryAfter ? { retryAfter } : null,
    message ? { message } : null
  );
}
if (!response.ok) {
  return { success: false, status: 'http_error', query, httpStatus: response.status, source: response.url || endpoint.href };
}
let data;
try {
  data = await response.json();
} catch {
  return { success: false, status: 'invalid_json', query, source: response.url || endpoint.href };
}
if (!data || typeof data !== 'object' || !Array.isArray(data.items) || typeof data.total_count !== 'number') {
  return { success: false, status: 'schema_changed', query, source: response.url || endpoint.href };
}
if (data.items.length === 0) {
  return {
    success: true,
    status: 'empty',
    query,
    repositories: [],
    total: 0,
    sources: { api: response.url || endpoint.href, page: pageUrl.href }
  };
}
const repositories = data.items
  .slice(0, limit)
  .map(item => {
    const fullName = String((item && item.full_name) || '').trim();
    const slash = fullName.indexOf('/');
    const owner = String((item && item.owner && item.owner.login) || (slash > 0 ? fullName.slice(0, slash) : '')).trim();
    const repo = String((item && item.name) || (slash > 0 ? fullName.slice(slash + 1) : '')).trim();
    const url = String((item && item.html_url) || (owner && repo ? 'https://github.com/' + owner + '/' + repo : '')).trim();
    const stars = Number(item && item.stargazers_count);
    const forks = Number(item && item.forks_count);
    return {
      owner,
      repo,
      url,
      description: String((item && item.description) || '').trim().slice(0, 500),
      language: String((item && item.language) || '').trim(),
      stars: Number.isFinite(stars) && stars >= 0 ? Math.floor(stars) : 0,
      forks: Number.isFinite(forks) && forks >= 0 ? Math.floor(forks) : 0,
      updatedAt: String((item && item.updated_at) || '').trim(),
      topics: Array.isArray(item && item.topics) ? item.topics.filter(t => typeof t === 'string').slice(0, 10) : []
    };
  })
  .filter(item => /^[A-Za-z0-9._-]+$/.test(item.owner) && /^[A-Za-z0-9._-]+$/.test(item.repo) && /^https:\/\/github\.com\/[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+$/.test(item.url));
if (!repositories.length) {
  return { success: false, status: 'schema_changed', query, source: response.url || endpoint.href };
}
return {
  success: true,
  status: 'ok',
  query,
  repositories,
  total: Math.max(repositories.length, Math.floor(data.total_count)),
  sources: { api: response.url || endpoint.href, page: pageUrl.href }
};
